// The icons of the app: the line icons of the design system (design/icons, 24 x 24, 1.6px stroke, currentColor) as
// one inline sprite, app/icons.svg (generated by scripts/make_icons.py), loaded once and put at the start of the
// body. A button declares its icon with data-icon="<name>" and applyI18n / applyIcons draw it before the label;
// labels built in JavaScript use icon(name). No emoji or glyph characters in labels (design system, Content).
let loading = null;

export function loadIcons() {
  if (loading) return loading;
  loading = fetch(new URL('../../icons.svg', import.meta.url), { cache: 'no-cache' })
    .then(r => { if (!r.ok) throw new Error(`icons: HTTP ${r.status}`); return r.text(); })
    .then(svg => {
      if (document.getElementById('pvpIcons')) return;
      const box = document.createElement('div');
      box.id = 'pvpIcons';
      box.setAttribute('aria-hidden', 'true');
      box.innerHTML = svg;
      document.body.prepend(box);
    })
    .catch(e => console.warn('[icons] sprite not loaded: buttons keep their labels', e));
  return loading;
}

// the markup of one icon; cls: extra classes (sm, lg …)
export const icon = (name, cls = '') => `<svg class="icon${cls ? ' ' + cls : ''}" aria-hidden="true" focusable="false"><use href="#i-${name}"/></svg>`;

// draws the icon of every [data-icon] element of root that does not have one yet
export function applyIcons(root = document) {
  for (const el of root.querySelectorAll('[data-icon]')) {
    if (!el.querySelector(':scope > svg.icon')) el.insertAdjacentHTML('afterbegin', icon(el.dataset.icon));
  }
}
